<?php
namespace App\Services;
class TotpService{private const ALPHABET='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';public function secret(int$bytes=20):string{return$this->encode(random_bytes($bytes));}public function verify(string$secret,string$code,int$window=1):bool{if(!preg_match('/^\d{6}$/',$code))return false;$counter=(int)floor(time()/30);for($offset=-$window;$offset<=$window;$offset++)if(hash_equals($this->code($secret,$counter+$offset),$code))return true;return false;}public function uri(string$secret,string$email):string{return'otpauth://totp/'.rawurlencode('DekkPilot:'.$email).'?'.http_build_query(['secret'=>$secret,'issuer'=>'DekkPilot','algorithm'=>'SHA1','digits'=>6,'period'=>30]);}private function code(string$secret,int$counter):string{$key=$this->decode($secret);$binary=pack('N2',($counter>>32)&0xffffffff,$counter&0xffffffff);$hash=hash_hmac('sha1',$binary,$key,true);$offset=ord($hash[19])&15;$value=((ord($hash[$offset])&127)<<24)|((ord($hash[$offset+1])&255)<<16)|((ord($hash[$offset+2])&255)<<8)|(ord($hash[$offset+3])&255);return str_pad((string)($value%1000000),6,'0',STR_PAD_LEFT);}private function encode(string$data):string{$bits='';foreach(str_split($data)as$char)$bits.=str_pad(decbin(ord($char)),8,'0',STR_PAD_LEFT);$out='';foreach(str_split($bits,5)as$chunk){$chunk=str_pad($chunk,5,'0');$out.=self::ALPHABET[bindec($chunk)];}return$out;}private function decode(string$value):string{$bits='';foreach(str_split(strtoupper(preg_replace('/[^A-Z2-7]/','',$value)))as$char){$index=strpos(self::ALPHABET,$char);if($index===false)continue;$bits.=str_pad(decbin($index),5,'0',STR_PAD_LEFT);}$out='';foreach(str_split($bits,8)as$chunk)if(strlen($chunk)===8)$out.=chr(bindec($chunk));return$out;}}
